contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public entry that the checker will call
    function run(uint256 seedDrugs) public payable {
        // must seed the market first; seedMarket requires marketDrugs == 0
        // seedMarket is payable, but in P it does not check msg.value; still pass zero value
        c.seedMarket{value: 0}(seedDrugs);

        // record initial observations for this test contract (which is msg.sender for subsequent calls)
        uint256 beforeKilos = c.getMyKilo();
        // beforeKilos should be 0 for fresh deployment, but we do not require it here; we will assert behavior relative to it

        // First attempt to get free kilo: should succeed iff caller had zero kilos (function reverts when Kilos[msg.sender] != 0)
        bool firstReverted;
        try c.getFreeKilo() {
            firstReverted = false;
        } catch {
            firstReverted = true;
        }

        // Observe values after first attempt
        uint256 afterKilos = c.getMyKilo();
        uint256 lastCollectAfter;
        // lastCollect has no direct getter; but getDrugsSinceLastCollect depends on lastCollect and kilos; we can check getMyDrugs to infer changes.
        uint256 afterDrugs = c.getMyDrugs();

        // Now call getFreeKilo again to check it must revert on second call (since Kilos[msg.sender] should now be non-zero)
        bool secondReverted;
        try c.getFreeKilo() {
            secondReverted = false;
        } catch {
            secondReverted = true;
        }

        // General rule asserted:
        // If the first getFreeKilo call did not revert, then after it the caller's kilos increased by exactly c.STARTING_KILOS and getFreeKilo must revert on a subsequent call.
        // If the first call reverted, then kilos did not increase and the second call must also revert.
        uint256 startingKilos = c.STARTING_KILOS();

        assert(
            // case A: first call succeeded
            (!firstReverted && afterKilos == SafeCastToUint256(startingKilos) + beforeKilos && secondReverted)
            ||
            // case B: first call reverted -> kilos unchanged and second also reverts
            (firstReverted && afterKilos == beforeKilos && secondReverted)
        );
    }

    // helper to convert public getter uint256 (already uint256) but keeps reading via external call only
    function SafeCastToUint256(uint256 x) internal pure returns (uint256) { return x; }

    receive() external payable {}
}

