contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public entry that the checker will call
    // params: amount to seed market with, and an arbitrary number of seconds to advance simulated production via lastCollect isn't possible here,
    // so we only test immediate sell after seeding (no produced drugs). No Ether is sent when calling sellDrugs.
    function run(uint256 seedDrugs) public payable {
        // seed the market so initialized becomes true
        c.seedMarket{value: 0}(seedDrugs);

        // record observable state before the sell attempt
        uint256 beforeMarket = c.marketDrugs();
        uint256 beforeClaimed = c.claimedDrugs(address(this));
        uint256 beforeBalanceC = address(c).balance;

        // attempt to sell immediately and capture whether it reverted
        bool reverted;
        try c.sellDrugs() {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 afterMarket = c.marketDrugs();
        uint256 afterClaimed = c.claimedDrugs(address(this));
        uint256 afterBalanceC = address(c).balance;

        // General rule (asserted): If the call succeeded, then claimedDrugs for this contract is 0 afterwards,
        // and marketDrugs has not decreased (it increases by at least the sold-drugs amount, so afterMarket >= beforeMarket),
        // and the contract's balance decreased by at most the dev fee (i.e., afterBalanceC <= beforeBalanceC).
        // If the call reverted, state must remain unchanged for these observable fields.
        assert(
            (reverted && afterClaimed == beforeClaimed && afterMarket == beforeMarket && afterBalanceC == beforeBalanceC)
            ||
            (!reverted && afterClaimed == 0 && afterMarket >= beforeMarket && afterBalanceC <= beforeBalanceC)
        );
    }

    // accept Ether if c sends any here
    receive() external payable {}
}

