contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public entry that the checker will call
    function run(address ref) public payable {
        require(true);

        // Ensure contract seeded if not initialized: seedMarket requires marketDrugs==0 and is payable
        // If not initialized, try to seed with 1 to enable collect; otherwise proceed.
        bool wasInitialized = c.initialized();
        if (!wasInitialized) {
            // send 1 wei to seedMarket and set marketDrugs to 1
            require(address(this).balance >= 1);
            c.seedMarket{value: 1}(1);
        }

        // Ensure caller has starting kilos by calling getFreeKilo if they have zero kilos
        uint256 beforeKilos = c.getMyKilo();
        if (beforeKilos == 0) {
            c.getFreeKilo();
        }

        // Observe pre-call values
        uint256 preClaimed = c.claimedDrugs(address(this));
        uint256 preKilos = c.getMyKilo();
        uint256 preMarket = c.marketDrugs();
        uint256 preLastCollect = c.lastCollect(address(this));

        // Compute drugs that would be produced since last collect via public getter
        uint256 preMyDrugs = c.getMyDrugs();

        // Make the deciding call and record whether it reverted
        bool reverted;
        try c.collectDrugs(ref) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Read post-call observable state
        uint256 postClaimed = c.claimedDrugs(address(this));
        uint256 postRefClaimed = c.claimedDrugs(ref);
        uint256 postKilos = c.getMyKilo();
        uint256 postMarket = c.marketDrugs();
        uint256 postLastCollect = c.lastCollect(address(this));

        // General rule asserted:
        // If collectDrugs did NOT revert then:
        //  - caller's lastCollect was updated (non-decrease and not equal to previous if time advanced)
        //  - caller's Kilos increased by exactly floor(preMyDrugs / DRUGS_TO_PRODUCE_1KILO)
        //  - caller's claimedDrugs is reset to zero (public claimedDrugs)
        //  - marketDrugs increased by at least floor(preMyDrugs / 10)
        // If collectDrugs reverted then nothing is required (we only assert reverted==true OR the above holds).

        uint256 producedKilos = preMyDrugs / c.DRUGS_TO_PRODUCE_1KILO();
        uint256 expectedPostKilos = preKilos + producedKilos;
        uint256 minMarketIncrease = preMyDrugs / 10;

        assert(
            reverted
            || (
                postLastCollect >= preLastCollect
                && postKilos == expectedPostKilos
                && postClaimed == 0
                && postMarket >= preMarket + minMarketIncrease
            )
        );
    }

    receive() external payable {}
}

