contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public entry that the checker will call
    function run() public payable {
        require(true);

        // Ensure contract is initialized: if not, seedMarket by sending 1 wei and setting marketDrugs to 1
        bool init = c.initialized();
        if (!init) {
            require(address(this).balance >= 1);
            c.seedMarket{value: 1}(1);
        }

        // Ensure caller has some kilos so getMyDrugs() can be > 0: if zero, give starting kilos
        uint256 beforeKilos = c.getMyKilo();
        if (beforeKilos == 0) {
            c.getFreeKilo();
        }

        // Read pre-call observables
        uint256 preClaimed = c.claimedDrugs(address(this));
        uint256 preMyDrugs = c.getMyDrugs();
        uint256 preMarket = c.marketDrugs();
        uint256 contractBalBefore = address(c).balance;
        uint256 selfBalBefore = address(this).balance;

        // Make the deciding call at top-level and capture whether it reverted
        bool reverted;
        try c.sellDrugs() {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Read post-call observables
        uint256 postClaimed = c.claimedDrugs(address(this));
        uint256 postMarket = c.marketDrugs();
        uint256 contractBalAfter = address(c).balance;
        uint256 selfBalAfter = address(this).balance;

        // Compute expected values via public view functions
        uint256 calcSell = c.calculateDrugSell(preMyDrugs);
        uint256 fee = c.devFee(calcSell);
        uint256 expectedPayout = 0;
        // avoid underflow in case calcSell < fee (though devFee should be <= calcSell normally)
        if (calcSell >= fee) { expectedPayout = calcSell - fee; }

        // Single general assertion: either the call reverted, or the observable invariants hold
        assert(
            reverted
            || (
                // claimedDrugs for caller is reset to 0 after successful sell
                postClaimed == 0
                // contract balance decreased by at most the payout + fee (i.e., by calcSell)
                && contractBalBefore >= contractBalAfter
                // the contract's balance decreased by exactly the payout+fee when funds were available
                && (contractBalBefore - contractBalAfter == calcSell || contractBalBefore - contractBalAfter <= calcSell)
                // the test contract's balance increased by at most expectedPayout (received funds)
                && (selfBalAfter >= selfBalBefore ? selfBalAfter - selfBalBefore == expectedPayout : true)
                // marketDrugs increased by at least preMyDrugs (sellDrugs does marketDrugs += hasDrugs)
                && postMarket >= preMarket + preMyDrugs
            )
        );
    }

    receive() external payable {}
}

