contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public test entry; provide a param to seed market and then call getFreeKilo
    function run(uint256 seedDrugs) public payable {
        // must seed market first so contract is initialized
        // seedMarket is payable; send along any Ether already present in this contract (none required)
        // call seedMarket to set initialized=true and marketDrugs=seedDrugs
        c.seedMarket(seedDrugs);

        // read STARTING_KILOS and DRUGS_TO_PRODUCE_1KILO via public getters
        uint256 starting = c.STARTING_KILOS();
        uint256 perKilo = c.DRUGS_TO_PRODUCE_1KILO();

        // ensure our test caller (this contract) currently has zero kilos so getFreeKilo can be called
        // The contract's getMyKilo() returns Kilos[msg.sender]; it should be zero initially for fresh c
        uint256 beforeKilos = c.getMyKilo();

        // precondition required so getFreeKilo doesn't revert: Kilos[msg.sender]==0 and initialized==true
        require(beforeKilos == 0);

        // perform the state-changing call under test
        c.getFreeKilo();

        // read afterward values
        uint256 afterKilos = c.getMyKilo();
        uint256 drugsSince = c.getDrugsSinceLastCollect(address(this));

        // general invariant to assert:
        // 1) afterKilos equals starting kilos provided by contract
        // 2) drugsSince (produced since lastCollect) is at most perKilo * afterKilos
        // This encodes that getFreeKilo sets Kilos to STARTING_KILOS and that production can't exceed the cap
        assert(afterKilos == starting && drugsSince <= perKilo * afterKilos);
    }

    receive() external payable { }
}
